  userId?: string;
  completed?: boolean;
}

export interface ListTodosResponse {
  todos: Todo[];
  total: number;
}

export interface CreateTodoBody {
  userId: string;
  title: string;
}

export interface UpdateTodoBody {
  title?: string;
  completed?: boolean;
}

export interface DeleteTodoResponse {
  deleted: boolean;
}

