// Internals
// ---------------------------------------------------------------------------

export interface ClientOptions {
  /** Base URL prefix; defaults to the contract's baseUrl. */
  baseUrl?: string;
  /** Custom fetch implementation (e.g. for tests / non-browser runtimes). */
  fetch?: typeof fetch;
}

