      return request<User>("POST", "/users", { body });
    },

    // GET /todos — list todos, optionally filtered by owner.
    listTodos(query?: ListTodosQuery): Promise<ListTodosResponse> {
      return request<ListTodosResponse>("GET", "/todos", { query });
    },

